import time
import traceback

from itertools import cycle, islice
from typing import List, Union, Optional

from taf.config.testline import PduPort
from taf.hw.pdu import pdu

from taf.rfrl.csv4all.resources.test_cases.csv4all_test import Node, method_decorator, test_logger
from taf.rfrl.csv4all.resources.test_cases.radio_module_reset_test import RadioModuleResetTest
from taf.rfrl.csv4all.resources.utilities.exceptions import PduFormatError
from taf.rfrl.csv4all.resources.utilities.utilities import wait_until_success


class RadioModulePowerReset(RadioModuleResetTest):
    pdu = pdu()

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 rmods_with_pdu_ports: List[dict], report: bool = True,
                 calculate_kpi: bool = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: str = None,
                 qc_id: str = None, qc_project: str = None, customers_list: Union[str, list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: bool = False, l3_call_method: Optional[callable] = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, stop_test_after_fail, l3_call_method,
                         detailed_console_log, collect_passed_logs=collect_passed_logs)
        self.rmods_with_pdu_ports = iter(islice(cycle(rmods_with_pdu_ports), 2*self.iterations_per_node))

    def test_operation(self, node):
        rmod = next(self.rmods_with_pdu_ports)
        rmod_sn = list(rmod.keys())[0]
        rmod_distname = [rmod_distname for rmod_distname, rmod_details in node.radioModules.items()
                         if rmod_sn == rmod_details.get("Serial Number")][0]
        self.add_allowed_specific_faults(node, ["10", "4589"], rmod_distname)
        self.add_faults_on_shared_rmod(node, rmod_distname, self.allowed_faults_on_shared_rmods)
        test_logger(f"Starting reset via PDU: {rmod_distname}")
        self.rmod_reset_via_pdu(rmod)
        self.wait_till_rmod_is_reseted(node, rmod_distname)
        if self.l3_call_method:
            self.set_l3_all_dependent_cells(node, rmod_distname)

    @method_decorator()
    def rmod_reset_via_pdu(self, rmod: dict):
        # Normalize all keys in the input dictionary to lowercase
        def normalize_keys(data):
            if isinstance(data, dict):
                return {key.lower(): normalize_keys(value) for key, value in data.items()}
            elif isinstance(data, list):
                return [normalize_keys(item) for item in data]
            else:
                return data

        # Normalize the rmod dictionary
        rmod_normalized = normalize_keys(rmod)
        pdu_details = list(rmod_normalized.values())[0]
        test_logger(f"PDU details: {pdu_details}")

        if isinstance(pdu_details, PduPort):
            self.pdu.setup_pdu(pdu_details.pdu)
            self.pdu.reset_ports([pdu_details])
        elif isinstance(pdu_details, dict):
            pdu_kwargs = {
                "model": pdu_details.get("model"),
                "host": pdu_details.get("host"),
            }
            if "version" in pdu_details:
                pdu_kwargs["version"] = pdu_details["version"]
            if "timeout" in pdu_details:
                pdu_kwargs["timeout"] = pdu_details["timeout"]
            if "snmp_user" in pdu_details:
                # Normalize keys in snmp_user dictionary
                snmp_user = normalize_keys(pdu_details["snmp_user"])
                pdu_kwargs["snmp_user"] = {
                    "userName": snmp_user.get("username", "administrator"),
                    "authKey": snmp_user.get("authkey", "password"),
                    "privKey": snmp_user.get("privkey", "password"),
                    "authProtocol": snmp_user.get("authprotocol", "MD5"),
                    "privProtocol": snmp_user.get("privprotocol", "AES"),
                }
            if "num_of_ports" in pdu_details:
                pdu_kwargs["num_of_ports"] = pdu_details["num_of_ports"]
            if "login" in pdu_details:
                pdu_kwargs["login"] = pdu_details["login"]
            if "password" in pdu_details:
                pdu_kwargs["password"] = pdu_details["password"]
            if "protocol" in pdu_details:
                pdu_kwargs["protocol"] = pdu_details["protocol"]
            if "community" in pdu_details:
                pdu_kwargs["community"] = pdu_details["community"]

            self.pdu.setup_pdu(**pdu_kwargs)
            self.pdu.reset_ports(
                pdu_details["port"] if isinstance(pdu_details["port"], list)
                else [pdu_details["port"]],
                time_interval=10,
            )
        else:
            test_logger(
                "Wrong format of Pdu Details provided!\nPlease provide either instance of PduPort class, or "
                "dictionary with host, model(and version if needed), port keys according to example in guide!\n"
                "Aborting Test!",
                "error",
            )
            raise PduFormatError("Wrong Format of PDU! Aborting test!")

        try:
            self.pdu.teardown_pdu()
        except NotImplementedError as e:
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug")

    @method_decorator()
    def wait_till_rmod_is_reseted(self, node, rmod_distname: str):
        test_logger("Waiting on RMOD reset")
        wait_until_success(120, 5, self.verify_if_rmod_is_reseted, node, rmod_distname)
        test_logger("RMOD reset completed")

    @method_decorator()
    def verify_if_rmod_is_reseted(self, node, rmod_distname):
        node.btsverify.set_current_bts_info()
        rmod_status = node.btsverify.rmod_verifier.get_module_status(rmod_distname)
        rmod_reseted = [rmod for rmod, states in rmod_status.items()
                      if any("Error" in state_value for state_value in states.values())]
        if not rmod_reseted:
            raise

    @method_decorator()
    def set_modules_eligible_for_test(self):
        pass
